import{_ as t,o as _,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Day CERN 2019: Ceph Supporting Genetic Research at Wellcome Sanger Institute - Matthew Vernon","description":"","frontmatter":{"title":"Ceph Day CERN 2019: Ceph Supporting Genetic Research at Wellcome Sanger Institute - Matthew Vernon","date":"2020-08-25T00:00:00.000Z","updated":"2020-08-26T00:00:00.000Z","tags":["Ceph","Distributed Storage","Genomic Research","OpenStack","RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Day_CERN_2019_-_Ceph_Supporting_Genetic_Research_at_Wellcome_Sanger_Institute_-_Matthew_Vernon.md","filePath":"posts/2020/Ceph_Day_CERN_2019_-_Ceph_Supporting_Genetic_Research_at_Wellcome_Sanger_Institute_-_Matthew_Vernon.md","lastUpdated":1780459816000}'),p={name:"posts/2020/Ceph_Day_CERN_2019_-_Ceph_Supporting_Genetic_Research_at_Wellcome_Sanger_Institute_-_Matthew_Vernon.md"};function a(n,e,r,o,h,s){return _(),i("div",null,[...e[0]||(e[0]=[l("<p>在CERN 2019年的Ceph Day会议上，Dr. Vernon分享了他在位于英国剑桥外的Wellcome Sanger研究所使用Ceph的经验。以下是对会议内容的详细总结：</p><p>会议背景：</p><ul><li>Sanger研究所是全球领先的基因组研究和基因测序中心，拥有约50PB的数据存储需求。</li><li>该研究所使用LSF集群进行批量计算，并提供Lustre作为快速临时存储。</li></ul><p>Ceph的引入与应用：</p><ul><li>2016年，研究所开始使用Ceph，最初部署在三个服务器上，提供3PB的原始容量。</li><li>Ceph主要用于支持OpenStack，提供更灵活的计算环境，特别是通过Ceph的RGW（RADOS Gateway）提供S3服务，结果非常受欢迎。</li></ul><p>Ceph的扩展与管理：</p><ul><li>随着需求增长，Ceph集群迅速扩展，到2017年底已达到18PB的容量。</li><li>使用Ceph Ansible进行集群管理，确保配置的一致性和自动化。</li><li>引入了HAProxy来优化RGW服务的性能和可靠性。</li></ul><p>挑战与解决方案：</p><ul><li>面临的主要挑战包括大规模删除操作和用户尝试将S3用作POSIX文件系统的问题。</li><li>通过改进Ceph的删除命令和引入HAProxy来解决这些问题，提高了服务的稳定性和性能。</li></ul><p>未来展望：</p><ul><li>计划增加专门的RGW硬件，以进一步优化性能。</li><li>继续支持UK BioBank等大型项目，预计将处理更多的基因组数据。</li></ul><p>决定事项：</p><ul><li>继续使用和扩展Ceph集群，优化RGW服务。</li><li>引入专门的硬件和进一步的软件优化，以应对大规模数据处理的需求。</li></ul><p>后续行动计划：</p><ul><li>实施硬件升级，增加专门的RGW服务器。</li><li>持续监控和优化Ceph集群的性能，确保服务的稳定性和可靠性。</li><li>探索更多Ceph在基因组研究中的应用场景，以支持更多的科学研究需求。</li></ul><p>改进后的总结确保了关键细节、讨论的主要议题、决定的事项以及后续的行动计划都被准确反映。同时，保留了计算机科学/ceph相关领域的英文原文关键词，如Ceph、distributed storage、CRUSH algorithm、high availability、scalability、object storage等。</p>",16)])])}const u=t(p,[["render",a]]);export{C as __pageData,u as default};
